export function FixedHeader({
  title = "{{title}}",
  height = {{height}},
  bg = "{{bg}}",
  shadow = {{shadow}},
}) {
  const lines = [
    "Fixed positioning takes the header out of normal document flow, so it sits on top of content rather than pushing it down.",
    "Scroll this area and the header stays pinned to the top edge of its positioned container.",
    "A third line of body copy.",
    "A fourth line, so the scrollbar actually appears.",
    "And a fifth to be sure.",
  ];
  return (
    <div style={{ position: "relative", height: 170, overflow: "hidden", border: "1px solid #24143022", fontFamily: "system-ui, sans-serif", fontSize: 13, lineHeight: 1.6, color: "#241430" }}>
      <header style={{ position: "absolute", top: 0, left: 0, right: 0, zIndex: 2, height, background: bg, color: "#FAF7F2", display: "flex", alignItems: "center", padding: "0 14px", fontWeight: 700, boxSizing: "border-box", boxShadow: shadow ? "0 4px 10px rgba(36,20,48,.25)" : "none" }}>{title}</header>
      <div style={{ height: "100%", overflowY: "auto", boxSizing: "border-box", padding: `${height}px 14px 14px`, background: "#FAF7F2" }}>
        {lines.map((l, i) => <p key={i} style={{ margin: "10px 0 0", color: "#241430cc" }}>{l}</p>)}
      </div>
    </div>
  );
}
